import health from '@service.health';
import core from './health-core.js';

export const DATA_TYPES = health.DATA_TYPES;

export function getRecent(dataTypes) {
  return health
    .getRecentSamples({ dataTypes })
    .then((list) => core.normalizeRecent(list))
    .catch(() => []);
}

export function subscribe(dataType, onSample, onError) {
  health.subscribeSample({
    dataType,
    callback: (sample) => {
      const normalized = core.normalizeSample(dataType, sample);
      if (normalized) onSample(normalized);
    },
    fail: (data, code) => {
      if (onError) onError(core.normalizeError(code));
    },
  });
}

export function unsubscribe(dataType) {
  health.unsubscribeSample({ dataType });
}


import sensor from '@system.sensor';

export function subscribeAccelerometer(onSample, onError) {
  try {
    sensor.subscribeAccelerometer({
      interval: 'game',
      callback: (sample) => {
        onSample({ x: sample.x, y: sample.y, z: sample.z });
      },
      fail: (message, code) => {
        if (onError) onError({ message, code });
      },
    });
  } catch (error) {
    if (onError) onError({ message: error.message, code: 200 });
  }
}

export function unsubscribeAccelerometer() {
  try {
    sensor.unsubscribeAccelerometer();
  } catch (error) {
    console.log('取消加速度订阅失败', error.message);
  }
}

function unique(values) {
  return Array.from(new Set(Array.isArray(values) ? values : []));
}

