--- health_core_motion ---
// service.health 返回值的纯数据规范化层。

function validData(data) {
  return data && typeof data.value === 'number' && typeof data.timeStamp === 'number';
}

function normalizeRecent(list) {
  if (!Array.isArray(list)) return [];
  const normalized = [];
  for (let i = 0; i < list.length; i += 1) {
    const item = list[i];
    if (!item || !validData(item.data)) continue;
    normalized.push({
      ok: true,
      dataType: item.dataType,
      value: item.data.value,
      timeStamp: item.data.timeStamp,
    });
  }
  return normalized;
}

function normalizeSample(dataType, sample) {
  if (!validData(sample)) return null;
  return {
    ok: true,
    dataType,
    value: sample.value,
    timeStamp: sample.timeStamp,
  };
}

function normalizeError(code) {
  return { ok: false, code, unsupported: code === 203 };
}

module.exports = { normalizeRecent, normalizeSample, normalizeError };


import sensor from '@system.sensor';

export function subscribeAccelerometer(onSample, onError) {
  try {
    sensor.subscribeAccelerometer({
      interval: 'game',
      callback: (sample) => {
        onSample({ x: sample.x, y: sample.y, z: sample.z });
      },
      fail: (message, code) => {
        if (onError) onError({ message, code });
      },
    });
  } catch (error) {
    if (onError) onError({ message: error.message, code: 200 });
  }
}

export function unsubscribeAccelerometer() {
  try {
    sensor.unsubscribeAccelerometer();
  } catch (error) {
    console.log('取消加速度订阅失败', error.message);
  }
}

// 节奏拳纯逻辑层。动作识别只依赖相邻加速度向量的变化。

const GAME_MS = 30000;
const HIT_WINDOW_MS = 350;

function finite(value) {
  return typeof value === 'number' && Number.isFinite(value);
}

function validSample(sample) {
  return sample && finite(sample.x) && finite(sample.y) && finite(sample.z);
}

function vectorDelta(previous, current) {
  const dx = current.x - previous.x;
  const dy = current.y - previous.y;
  const dz = current.z - previous.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

function createPunchDetector(options) {
  const config = options || {};
  const threshold = finite(config.threshold) ? config.threshold : 4.5;
  const cooldownMs = finite(config.cooldownMs) ? config.cooldownMs : 350;
  let previous = null;
  let lastPunchAt = -Infinity;

  return {
    push(sample, timestamp) {
      if (!validSample(sample) || !finite(timestamp)) return false;
      if (!previous) {
        previous = sample;
        return false;
      }
      const movement = vectorDelta(previous, sample);
      previous = sample;
      if (movement < threshold || timestamp - lastPunchAt < cooldownMs) return false;
      lastPunchAt = timestamp;
      return true;
    },
  };
}

function scorePunch(punchAt, beatAt) {
  const difference = Math.abs(punchAt - beatAt);
  if (difference <= 120) return { points: 100, grade: 'perfect' };
  if (difference <= 250) return { points: 70, grade: 'good' };
  if (difference <= HIT_WINDOW_MS) return { points: 40, grade: 'hit' };
  return { points: 0, grade: 'miss' };
}

function beatIntervalForHeartRate(heartRate) {
  if (!finite(heartRate) || heartRate < 120) return 1000;
  if (heartRate < 150) return 1200;
  return 1400;
}

function createStats() {
